Translate("frFR", "prospector-ryedol", {
	title = "Prospecteur Ryedol",
	subtitle = "Prospecteur de la Ligue des explorateurs",
	found = "Le camp de la Ligue au sud du Site de fouilles d'Hammertoe",
	hint = [=[Trouvez le prospecteur qui a survécu à la chute du chantier d'Hammertoe.]=],
	allegiance = "Ligue des explorateurs",
	aliases = { "Ryedol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le prospecteur Ryedol travaillait sous les ordres de l'explorateur Hammertoe Grez à son chantier au nord des {link:badlands}Terres ingrates{/link}. Quand le clan Shadowforge attaqua, il fut l'un des rares à s'échapper. Il tient désormais un petit camp au sud du site en ruine avec {link:sigrun-ironhew}Sigrun Ironhew{/link} et les autres survivants. Il parle sans détour, il est las, et il dit que chaque jour dans les Terres ingrates est un mauvais jour.]=],
		},
		{
			title = "Importance",
			text = [=[Ryedol est le fil qui relie le sort d'Hammertoe à {link:ironforge}Ironforge{/link}. Par lui, le royaume apprit que les Shadowforge ne se contentaient pas de piller. Ils cherchaient des secrets des titans, et le savoir qu'Hammertoe portait dans sa tête.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il échappa à l'attaque des Shadowforge contre le chantier d'Hammertoe.
• Il apprit par une carte griffonnée qu'Hammertoe avait été emmené vivant à {link:uldaman}Uldaman{/link}.
• Il envoya un chercheur dans la chambre forte retrouver son ancien maître.
• Il fit porter l'amulette d'Hammertoe à l'historien {link:historian-karnik}Karnik{/link}, à {link:ironforge}Ironforge{/link}, par la main d'un autre.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit de la vie de Ryedol avant les {link:badlands}Terres ingrates{/link}.]=],
		},
	},
	chapters = {
		{
			title = "La pioche porte-bonheur",
			hint = "Reprenez aux Shadowforge la pioche du prospecteur.",
			text = [=[Ryedol perdit tout dans l'attaque, jusqu'à sa pioche porte-bonheur. Il croyait qu'un des Shadowforge l'avait prise. Quand elle lui revint, il fut reconnaissant. Il fut aussi inquiet. Les {link:dark-iron-dwarves}Sombrefer{/link} n'avaient pas frappé le chantier au hasard, dit-il. Ils cherchaient quelque chose.]=],
		},
		{
			title = "Un signe d'espoir",
			hint = [=[Dites au prospecteur ce que révèle la carte griffonnée à la craie.]=],
			text = [=[Une carte fut trouvée près du chantier en ruine, portant un message griffonné à la craie : Hammertoe était emmené à {link:uldaman}Uldaman{/link}. Ryedol l'avait pleuré comme mort. Il comprit alors pourquoi les Shadowforge l'avaient épargné. Ils voulaient ce qu'Hammertoe savait des fouilles des titans. Les {link:dark-iron-dwarves}Sombrefer{/link} cherchaient depuis longtemps le moyen de construire des golems plus puissants. Hammertoe avait étudié les mêmes secrets afin de les en empêcher.]=],
		},
		{
			title = "Une question de foi",
			hint = [=[Apportez au prospecteur ce qu'Hammertoe a laissé derrière lui.]=],
			text = [=[Hammertoe fut retrouvé dans {link:uldaman}Uldaman{/link}, mais il était mourant. Il renvoya son amulette, l'œuvre de sa vie, et demanda qu'elle revienne à Ryedol. Ryedol dit qu'il avait été plus heureux quand il croyait son maître déjà mort. Puis il se reprit. Hammertoe avait travaillé avec l'historien {link:historian-karnik}Karnik{/link} d'{link:ironforge}Ironforge{/link}, et Karnik saurait ce que signifiait l'amulette. Ryedol la lui fit porter, pour que cette mort ne soit pas vaine.]=],
		},
	},
	mentions = {
		{ text = "Un {link:dwarves}nain{/link} et ses outils" },
		{ text = "Un signe d'espoir" },
		{ text = "Un signe d'espoir, envoyé dans {link:uldaman}Uldaman{/link}" },
		{ text = "Une question de foi, l'amulette d'Hammertoe rapportée" },
		{
			text = [=[Une question de foi, portée jusqu'à {link:ironforge}Ironforge{/link}]=],
		},
	},
	bonds = {
		{ id = "hammertoe-grez", name = "Hammertoe Grez", note = "son maître" },
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "partage son camp" },
		{ id = "historian-karnik", name = "Historien Karnik", note = "l'associé d'Hammertoe à Ironforge" },
	},
})

