	},
})

Translate("frFR", "garek", {
	title = "Garek",
	subtitle = "Agent du Kirin Tor",
	found = "Le Goulet de la Bourrasque, à l'ouest du Ravin de Lethlor",
	hint = "Trouvez le mage discret qui veille sur le Ravin de Lethlor.",
	allegiance = "Kirin Tor",
	sections = {
		{
			title = "Résumé",
			text = [=[{link:garek-bandarion}Garek{/link} est un mage envoyé dans les {link:badlands}Terres ingrates{/link} par un maître du {link:kirin-tor}Kirin Tor{/link}, Krasus. Le mage tient un camp solitaire près du {link:lethlor-ravine}Ravin de Lethlor{/link} et parle peu de sa mission, sinon pour dire qu'elle est de la plus haute importance et qu'elle concerne les troubles qui couvent dans le ravin.]=],
		},
		{
			title = "Importance",
			text = [=[{link:garek-bandarion}Garek{/link} montre que le {link:kirin-tor}Kirin Tor{/link} surveille toujours le vol noir, même en ces années troublées. Sous le {link:lethlor-ravine}Ravin de Lethlor{/link} reposent deux lieutenants d'{link:deathwing}Aile-de-mort{/link}, et son maître a décidé qu'aucun risque de les voir libérés ne pouvait être toléré.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il cherche le Signe de la Terre, la clé de la prison des drakes, volé par une bande d'ogres errants.
• Il apprit l'histoire de la prison et de ses bâtisseurs {link:dark-iron-dwarves}Sombrefer{/link}.
• Il a résolu que {link:blacklash}Blacklash{/link} et {link:hematus}Hematus{/link} ne doivent plus jamais s'éveiller.]=],
		},
		{
			title = "Non consigné",
			text = [=[{link:garek-bandarion}Garek{/link} ne dit pas qui il était avant d'entrer au service de son maître, et aucun registre ne le révèle.]=],
		},
	},
	chapters = {
		{
			title = "Le Signe de la Terre",
			hint = "Récupérez la clé volée pour le mage du Kirin Tor.",
			text = [=[Le Signe de la Terre fut forgé par les {link:dark-iron-dwarves}Sombrefer{/link} de la {link:angor-fortress}Forteresse d'Angor{/link} pour enchaîner deux des lieutenants d'{link:deathwing}Aile-de-mort{/link}, les drakes jumeaux {link:blacklash}Blacklash{/link} et {link:hematus}Hematus{/link}. Quand on le lui apporta, {link:garek-bandarion}Garek{/link} parla plus librement. Les dragons noirs étaient venus nicher dans le ravin. Les ogres avaient réussi à voler le Signe. On ne pouvait plus se fier à la prison.]=],
		},
		{
			title = "Rêves éternels",
			hint = "Mettez fin au danger des drakes de Lethlor.",
			text = [=[Grâce au Signe, les trois pierres runiques purent être retirées de leurs piliers et placées dans le Sceau de la Terre. Le sceau se brisa, et les drakes ne furent libres que le temps d'être abattus. {link:garek-bandarion}Garek{/link} demanda seulement que leurs rêves soient rendus éternels. Quand ce fut fait, il se prépara à rejoindre Krasus pour lui annoncer que le {link:kirin-tor}Kirin Tor{/link} n'avait plus à craindre les prisonniers de {link:lethlor-ravine}Lethlor{/link}.]=],
		},
	},
	mentions = {
		{ text = "Tremblements de terre, le Signe récupéré" },
		{ text = "Tremblements de terre, les drakes abattus" },
		{ text = "Le Sceau de la Terre" },
	},
	bonds = {
		{ id = "sigrun-ironhew", name = "Sigrun Ironhew", note = "lui a parlé de ceux qui aident" },
		{ id = "blacklash", name = "Blacklash", note = "un prisonnier de Lethlor" },
		{ id = "hematus", name = "Hematus", note = "un prisonnier de Lethlor" },
		{ id = "boss-tho-grun", name = "Chef Tho'grun", note = "a volé le Signe" },
	},
})

