Translate("frFR", "lotwil-veriatus", {
	title = "Lotwil Veriatus",
	subtitle = "Mage et bricoleur de Kharanos",
	found = "Son camp dans la Vallée de la poussière",
	hint = [=[Trouvez le mage gnome qui teste ses inventions dans la Vallée de la poussière.]=],
	allegiance = "Gnomes · Kharanos",
	aliases = { "Lotwil" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lotwil Veriatus est un {link:gnomes}gnome{/link} qui mêle alchimie, ingénierie et magie des arcanes au service de sa propre curiosité. Il est venu de {link:kharanos}Kharanos{/link} dans les {link:badlands}Terres ingrates{/link} pour construire sa plus grande œuvre : des entraves de lien élémentaire, qui permettraient à un mage de commander des élémentaires bien plus puissants que tous ceux qu'on a jamais appelés. Son assistant {link:lucien-tosselwrench}Lucien{/link} et son maladroit serviteur mécanique, Servo, partagent son camp. Lotwil est brillant, distrait et joyeusement convaincu que chaque revers n'est qu'un petit revers.]=],
		},
		{
			title = "Importance",
			text = [=[Lotwil est un savant d'un vrai renom dans les sciences élémentaires, et même la {link:horde}Horde{/link} de {link:kargath}Kargath{/link} sollicite son jugement. Il a aussi un passé. Il y a longtemps, il combattit un {link:dark-iron-dwarves}Sombrefer{/link} qui détourna l'œuvre de sa vie pour en faire des armes, et il croyait cet ennemi mort.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie les élémentaires de roche des {link:badlands}Terres ingrates{/link} pour construire ses entraves.
• Il refroidit et renforce ses entraves avec de l'huile de givre et un appareil appelé gyrochronatome.
• Il invoque un gardien de pierre avec ses entraves achevées, ce qui ne se passe pas comme prévu.
• Il connaît les marques du fabricant de golems Argelmach.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques ne disent pas comment Lotwil et Argelmach se rencontrèrent, ni comment le {link:dark-iron-dwarves}Sombrefer{/link} s'empara de l'œuvre du {link:gnomes}gnome{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'étude des éléments",
			hint = [=[Rassemblez ce dont le gnome a besoin auprès des élémentaires de roche des Terres ingrates.]=],
			text = [=[Des éclats des élémentaires mineurs, des dalles des plus grands, et enfin les brassards de lien rocheux du plus grand d'entre eux. Chaque pièce permit à Lotwil d'éprouver ses sorts contre la matière de la roche vivante. Chaque essai se déroula comme il l'avait prédit. Il se mit à parler des élémentaires qu'il contrôlerait bientôt, et de la façon dont ils feraient honte à toutes les invocations passées.]=],
		},
		{
			title = "Ça va être difficile",
			hint = [=[Aidez le gnome à achever ses entraves, et affrontez ce qui s'ensuit.]=],
			text = [=[Les entraves étaient prêtes. Lotwil appela {link:lucien-tosselwrench}Lucien{/link} et Servo pour qu'ils en soient témoins, et il invoqua un gardien de pierre élémentaire. Celui-ci n'obéit pas. Quand la créature fut vaincue et ses entraves récupérées, Lotwil admit que ce n'était pas le résultat qu'il attendait. Il ne sut dire ce qui avait mal tourné. Il était content, dit-il, que sa magie ait été là pour renvoyer la créature chez elle.]=],
		},
		{
			title = "La révolte des machines",
			hint = [=[Portez l'éclat élémentaire marqué de Kargath jusqu'au camp du gnome.]=],
			text = [=[Les éclats venaient de golems des {link:burning-steppes}Steppes ardentes{/link}, et ils portaient des initiales. Quand Lotwil les vit, il devint blême. Il connaissait ces marques. Elles appartenaient à Argelmach, un {link:dark-iron-dwarves}Sombrefer{/link} qui avait plié l'œuvre de Lotwil à des fins maléfiques, et que Lotwil avait tué de sa propre main des années plus tôt. Quand la tête d'Argelmach fut rapportée des {red:blackrock-depths}Profondeurs de Blackrock{/red}, elle n'était pas de chair. C'était une machine faite à l'image d'Argelmach, et Lotwil craignit qu'une autre ne se lève pour prendre sa place.]=],
		},
	},
	mentions = {
		{ text = "L'étude des éléments : la roche" },
		{ text = "L'étude des éléments : la roche" },
		{ text = "L'étude des éléments : la roche" },
		{ text = "Refroidir les têtes" },
		{ text = "Gyro... quoi ?" },
		{ text = "Ça va être difficile" },
		{ text = "Ça va être difficile, l'engrenage livré" },
		{ text = "Ça va être difficile, le gardien déchaîné" },
		{
			text = [=[La révolte des machines, l'éclat rapporté de {link:kargath}Kargath{/link}]=],
		},
		{ text = "La révolte des machines, la tête d'Argelmach" },
	},
	bonds = {
		{ id = "lucien-tosselwrench", name = "Lucien Tosselwrench", note = "son assistant" },
		{ id = "hierophant-theodora-mulvadania", name = "Hiérophante Theodora Mulvadania", note = "sollicite son jugement" },
		{ id = "golem-lord-argelmach", name = "Seigneur golem Argelmach", note = "son vieil ennemi" },
	},
})

Translate("frFR", "lucien-tosselwrench", {
	title = "Lucien Tosselwrench",
	subtitle = "Assistant de Lotwil Veriatus",
	found = "Le camp de Lotwil dans la Vallée de la poussière",
	hint = [=[Parlez à l'assistant qui se tient prudemment à distance des travaux de Lotwil.]=],
	allegiance = "Kharanos",
	aliases = { "Lucien" },
	sections = {
		{
			title = "Résumé",
			text = [=[Lucien Tosselwrench est l'assistant de {link:lotwil-veriatus}Lotwil Veriatus{/link}, et il a appris de son maître plus que Lotwil ne le sait. À partir des recherches de Lotwil dans les {link:badlands}Terres ingrates{/link}, il a mis au point sa propre recette de potion, et il enchante des brassards avec la pierre en surplus que Lotwil rassemble. Il connaît aussi assez bien son maître pour se mettre à l'abri avant chaque expérience.]=],
		},
		{
			title = "Importance",
			text = [=[Lucien est la moitié pratique du camp de {link:lotwil-veriatus}Lotwil{/link}. Là où Lotwil voit le triomphe, Lucien voit les ennuis, et il s'y prépare.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rassemble des potions de soins et d'invisibilité au cas où les travaux de {link:lotwil-veriatus}Lotwil{/link} tourneraient mal.
• Il fabrique des brassards enchantés avec la pierre restante des élémentaires.
• Il remet l'engrenage numéro cinq, puis se met à couvert.]=],
		},
	},
	mentions = {
		{ text = "Pierre liquide" },
		{ text = "La pierre vaut mieux que le tissu" },
		{ text = "Ça va être difficile" },
		{ text = "Ça va être difficile" },
	},
	bonds = {
		{ id = "lotwil-veriatus", name = "Lotwil Veriatus", note = "son maître" },
	},
})

Translate("frFR", "rigglefuzz", {
	title = "Rigglefuzz",
	subtitle = "Cuisinier gobelin des Terres ingrates",
	found = "Le camp de la Vallée des crocs",
	hint = [=[Trouvez le gobelin qui fait cuire des ailes de charognard au milieu des Terres ingrates.]=],
	allegiance = "Gobelins",
	sections = {
		{
			title = "Résumé",
			text = [=[Rigglefuzz est un gobelin qui vit au cœur des {link:badlands}Terres ingrates{/link}, où il survit grâce à sa ruse. Il tient les bêtes à distance avec des bombes éclairantes, et il est fier de ses ailes de charognard au barbecue, dont l'odeur, prétend-il, peut attirer les affamés à des lieues à la ronde. Il a aussi une rancune. Les Shadowforge l'emmenèrent jadis à la {link:angor-fortress}Forteresse d'Angor{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[C'est Rigglefuzz qui enseigna aux Shadowforge le secret des étranges pierres d'{link:uldaman}Uldaman{/link}. Ils l'emmenèrent à la {link:angor-fortress}Forteresse d'Angor{/link} pour étudier deux sortes de pierres de la chambre forte, et il découvrit que, bien traitées, elles étaient des sources d'énergie stables et durables. Quand il le leur dit, ils le jetèrent dehors et se mirent à creuser pour en trouver d'autres.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fabrique des bombes éclairantes avec des perles bleues broyées, rapportées des récifs de la {link:stranglethorn-vale}Vallée de Strangleronce{/link}.
• Il cuisine des ailes de charognard et partage la recette avec ceux qui l'aident.
• Il veut les pierres d'énergie d'{link:uldaman}Uldaman{/link} pour ses propres appareils.]=],
		},
	},
	mentions = {
		{ text = "Ailes de charognard au barbecue" },
		{ text = "Pêche aux perles" },
		{ text = "Recette de bombe éclairante" },
		{ text = "Pierres d'énergie" },
	},
	bonds = {
		{ id = "martek-the-exiled", name = "Martek l'Exilé", note = "partage son camp" },
	},
})

Translate("frFR", "martek-the-exiled", {
	title = "Martek l'Exilé",
	subtitle = "Forgeron exilé",
	found = "Le camp de la Vallée des crocs",
	hint = [=[Trouvez le forgeron venu dans les Terres ingrates pour qu'on le laisse en paix.]=],
	allegiance = "Aucune",
	aliases = { "Martek" },
	sections = {
		{
			title = "Résumé",
			text = [=[Martek est un forgeron d'un grand talent, qui en sait plus sur le métal que presque quiconque. C'est aussi un homme traqué. Beaucoup voudraient le voir mort, et il s'attend à ce que chaque inconnu soit l'un d'eux. Il demande aux visiteurs s'ils viennent pour la hache qu'il fit pour {link:gath-ilzogg}Gath'Ilzogg{/link}, ou pour venger l'honneur d'une certaine duchesse Pamay, et dit que peu lui importe.]=],
		},
		{
			title = "Importance",
			text = [=[Martek trouva dans les {link:badlands}Terres ingrates{/link} un métal appelé indurium, qui résiste à la chaleur et aux contraintes mieux que tout autre. Le vrai minerai repose au fond d'{link:uldaman}Uldaman{/link}. Par lui, la nouvelle en parvint au {link:gnomes}gnome{/link} {link:fizzle-brassbolts}Fizzle Brassbolts{/link}, à {link:thousand-needles}Mille pointes{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il forgea une hache pour l'{link:ogres}ogre{/link} {link:gath-ilzogg}Gath'Ilzogg{/link}.
• Il éprouve les paillettes d'indurium que portent les troggs Stonevault.
• Il fait savoir à {link:fizzle-brassbolts}Fizzle Brassbolts{/link} que l'indurium peut servir à fabriquer les pistons de son bolide.]=],
		},
	},
	mentions = {
		{ text = "Martek l'Exilé" },
		{ text = "Indurium" },
		{ text = "Des nouvelles pour Fizzle" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "l'un des rares qui lui veulent du bien" },
		{ id = "rigglefuzz", name = "Rigglefuzz", note = "partage son camp" },
		{ id = "gath-ilzogg", name = "Gath'Ilzogg", note = "a acheté sa hache" },
	},
})

Translate("frFR", "warlord-goretooth", {
	title = "Seigneur de guerre Goretooth",
	subtitle = "Commandant de la Force expéditionnaire de Kargath",
	found = "Kargath",
	hint = [=[Parlez au seigneur de guerre qui commande l'armée de la Horde à Kargath.]=],
	allegiance = "Horde · Force expéditionnaire de Kargath",
	aliases = { "Goretooth" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le seigneur de guerre Goretooth commande la Force expéditionnaire de {link:kargath}Kargath{/link}, l'armée que la {link:horde}Horde{/link} entretient dans les {link:badlands}Terres ingrates{/link} pour combattre le {link:blackrock-clan}clan Blackrock{/link} et les {link:dark-iron-dwarves}Sombrefer{/link} du {link:blackrock-mountain}Mont Blackrock{/link}. C'est un soldat dur, trop occupé pour les visiteurs et trop fier pour montrer sa peur. Il parle par ordres. Ses avis de recherche sont affichés dans tout Kargath, et chacun promet un tribut à qui exécutera la sentence.]=],
		},
		{
			title = "Importance",
			text = [=[Goretooth mène la plus longue campagne de la {link:horde}Horde{/link} dans les {link:eastern-kingdoms}Royaumes de l'est{/link}. Sa force a durement souffert : le général sombrefer Angerforge a massacré sa 109e division. Goretooth a juré qu'Angerforge le paierait.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il commande la F.E.K. depuis {link:kargath}Kargath{/link}, avec ses officiers {link:lexlort}Lexlort{/link}, {link:galamav-the-marksman}Galamav{/link}, {link:shadowmage-vivian-lagrave}Vivian Lagrave{/link} et {link:hierophant-theodora-mulvadania}Theodora Mulvadania{/link}.
• Il affiche l'ordre de tuer les soldats Anvilrage du général Angerforge, dans les {red:blackrock-depths}Profondeurs de Blackrock{/red}.
• Il prépare l'opération qui traduira le Boucher de {link:blackrock-mountain}Blackrock{/link} en justice.
• Il ordonne la mort des maîtres du {red:blackrock-spire}Pic Blackrock{/red}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Rien n'est écrit du clan de Goretooth ni de ses actes avant la F.E.K.]=],
		},
	},
	chapters = {
		{
			title = "Abattre à vue",
			hint = [=[Répondez aux avis du seigneur de guerre contre les Sombrefer.]=],
			text = [=[Les avis furent placardés sur les murs de {link:kargath}Kargath{/link} au nom du seigneur de guerre. Les hommes d'Angerforge étaient des tueurs sans pitié, responsables du massacre de la 109e. Chaque garde, gardien et officier Anvilrage des Profondeurs devait être détruit. Goretooth promettait des tributs, et il promettait pire à Angerforge.]=],
		},
		{
			title = "Mort à Angerforge",
			hint = [=[Menez à terme l'opération du seigneur de guerre contre le général sombrefer.]=],
			text = [=[La dernière opération était celle que le seigneur de guerre attendait. Le général Angerforge, le Boucher de {link:blackrock-mountain}Blackrock{/link}, fut tué dans les Profondeurs. Goretooth parla enfin de justice, et il remit un médaillon de la F.E.K. à celui qui l'avait accomplie.]=],
		},
		{
			title = "L'ordre du seigneur de guerre",
			hint = "Exécutez l'ordre du seigneur de guerre au Pic Blackrock.",
			text = [=[Goretooth ordonna la mort de trois maîtres du Pic {link:blackrock-mountain}Blackrock{/link}, et demanda tous les documents trouvés parmi leurs affaires. Les documents lui revinrent. Quand il les lut, sa peau verte pâlit un instant. Ils disaient que Rend Blackhand vivait, un chef que l'on croyait tué depuis longtemps. Goretooth fit porter la nouvelle à {link:eitrigg}Eitrigg{/link} et à {link:thrall}Thrall{/link}, à {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[ABATTRE À VUE : nains {link:dark-iron-dwarves}Sombrefer{/link}]=],
		},
		{
			text = [=[ABATTRE À VUE : hauts dignitaires {link:dark-iron-dwarves}Sombrefer{/link}]=],
		},
		{ text = "Opération : mort à Angerforge" },
		{ text = "L'ordre du seigneur de guerre" },
		{ text = "La sagesse d'{link:eitrigg}Eitrigg{/link}" },
	},
	bonds = {
		{ id = "lexlort", name = "Lexlort", note = "son chef de la reconnaissance" },
		{ id = "galamav-the-marksman", name = "Galamav le Tireur d'élite", note = "l'un de ses officiers" },
		{ id = "eitrigg", name = "Eitrigg", note = "connaît le mieux les Blackrock" },
		{ id = "thrall", name = "Thrall", note = "son chef de guerre" },
	},
})

