	title = "Lexlort",
	subtitle = "Grand maître de la reconnaissance de la F.E.K.",
	found = "Kargath",
	hint = [=[Parlez au maître des éclaireurs de la Force expéditionnaire de Kargath.]=],
	allegiance = "Horde · Force expéditionnaire de Kargath",
	sections = {
		{
			title = "Résumé",
			text = [=[Le grand maître Lexlort dirige la reconnaissance de la Force expéditionnaire de {link:kargath}Kargath{/link}. C'est lui qui découvrit où les hauts officiers sombrefer entraînent leurs soldats. Il traqua le traître {link:grark-lorkrub}Grark Lorkrub{/link} à travers {link:searing-gorge}la Gorge des Vents brûlants{/link}, par la montagne et jusque dans les {link:burning-steppes}Steppes ardentes{/link}, où les {link:blackrock-clan}orcs Blackrock{/link} l'abritaient.]=],
		},
		{
			title = "Importance",
			text = [=[Lexlort est les yeux de la F.E.K. Il entretient ses espions, dont une à qui elle ne peut tout à fait se fier.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il ramène {link:grark-lorkrub}Grark Lorkrub{/link} dans des entraves de thorium pour qu'il réponde de sa traîtrise.
• Il envoie un chercheur sur les traces de Bijou, une agente gobeline qui prit l'argent de la F.E.K. et celui d'un second maître.
• Il reçoit le rapport de Bijou sur les {link:blackrock-clan}orcs Blackrock{/link}, et admet qu'elle s'est de nouveau tirée d'affaire.]=],
		},
	},
	mentions = {
		{ text = "{link:grark-lorkrub}Grark Lorkrub{/link}" },
		{ text = "Situation précaire" },
		{ text = "L'agente Bijou" },
		{ text = "Le rapport de reconnaissance de Bijou" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Seigneur de guerre Goretooth", note = "son commandant" },
		{ id = "grark-lorkrub", name = "Grark Lorkrub", note = "le traître qu'il a traqué" },
	},
})

Translate("frFR", "galamav-the-marksman", {
