			title = "Résumé",
			text = [=[Galamav le Tireur d'élite est un officier de la F.E.K., rude de langue et vif de regard. Il n'est pas tendre avec ses soldats, et il ne prétend pas qu'un piège soit autre chose. Son affaire, ce sont les worgs du Pic {link:blackrock-mountain}Blackrock{/link} et les soldats perdus de la {link:horde}Horde{/link} dans la montagne.]=],
		},
		{
			title = "Importance",
			text = [=[Quand une flèche frappa le grunt Gargal sur le sommet du crâne, Galamav trouva un mot attaché à la hampe : le dessin grossier d'un {link:orcs}orc{/link} derrière des barreaux, signé du commandant Gor'shak. Par Galamav, {link:kargath}Kargath{/link} apprit que l'un de ses commandants vivait encore, prisonnier dans les Profondeurs.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des chercheurs dans les {red:blackrock-depths}Profondeurs de Blackrock{/red} pour retrouver le commandant Gor'shak.
• Il ordonne la mort d'Halycon, la grande mère de meute des worgs {link:blackrock-mountain}Blackrock{/link}.]=],
		},
	},
	mentions = {
		{ text = "Le commandant Gor'shak" },
		{ text = "La maîtresse de la meute" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Seigneur de guerre Goretooth", note = "son commandant" },
		{ id = "commander-gor-shak", name = "Commandant Gor'shak", note = "un prisonnier dans les Profondeurs" },
	},
})

Translate("frFR", "shadowmage-vivian-lagrave", {
