		{
			title = "Résumé",
			text = [=[Vivian Lagrave est une mage de l'ombre des {link:forsaken}Réprouvés{/link} qui sert au sein de la Force expéditionnaire de {link:kargath}Kargath{/link}. Elle trouve les {link:badlands}Terres ingrates{/link} sans charme, et le confort de l'{link:the-apothecarium}Apothicarium{/link} lui manque. Elle est à Kargath pour une seule raison : les {link:dark-iron-dwarves}Sombrefer{/link} savent des choses que la {link:royal-apothecary-society}Société royale des apothicaires{/link} veut savoir, et elle entend les leur prendre.]=],
		},
		{
			title = "Importance",
			text = [=[Vivian est la main d'{link:undercity}Undercity{/link} dans la guerre de la {link:horde}Horde{/link} contre les {link:dark-iron-dwarves}Sombrefer{/link}. Elle étudie leurs breuvages, leur alchimie et la puissance qui anime leurs golems, toujours en vue d'usages conformes aux desseins de son peuple.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche la recette perdue de la bière Thunderbrew, volée par un {link:dark-iron-dwarves}Sombrefer{/link}, pour voir comment sa force pourrait être retournée contre les nains de l'{link:alliance}Alliance{/link}.
• Elle cherche la tablette de Darkstone, l'œuvre d'un alchimiste mort depuis longtemps, au {red:blackrock-spire}Pic Blackrock{/red}.
• Elle envoie à {link:undercity}Undercity{/link} les essences qui alimentent les golems sombrefer.]=],
		},
	},
	mentions = {
		{ text = "Vivian Lagrave" },
		{ text = "La recette perdue de la Thunderbrew" },
		{ text = "Vivian Lagrave et la tablette de Darkstone" },
		{ text = "La tablette de Darkstone" },
		{ text = "Le dernier élément" },
	},
	bonds = {
		{ id = "warlord-goretooth", name = "Seigneur de guerre Goretooth", note = "son commandant" },
	},
})

Translate("frFR", "hierophant-theodora-mulvadania", {
