• Elle lit les lettres G.L.A. dans les fragments.
• Elle envoie son échantillon à {link:lotwil-veriatus}Lotwil Veriatus{/link}, dans son camp à l'est de {link:kargath}Kargath{/link}.]=],
		},
	},
	mentions = {
		{ text = "La révolte des machines" },
		{ text = "La révolte des machines" },
	},
	bonds = {
		{ id = "lotwil-veriatus", name = "Lotwil Veriatus", note = "connaissait les marques" },
	},
})

