	},
})

Translate("frFR", "thal-trak-proudtusk", {
	title = "Thal'trak Proudtusk",
	subtitle = "Soldat de la F.E.K.",
	found = "Kargath",
	hint = [=[Parlez au soldat de Kargath qui attend des nouvelles de sa femme.]=],
	allegiance = "Horde · Force expéditionnaire de Kargath",
	aliases = { "Thal'trak" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thal'trak Proudtusk est un soldat de la Force expéditionnaire de {link:kargath}Kargath{/link}. Sa femme, Sha'ni, partit avec un peloton dans les {link:burning-steppes}Steppes ardentes{/link} pour découvrir ce que faisaient les ogres Firegut lors de leurs rituels. C'était il y a des semaines. Personne de son peloton n'est revenu, et le seigneur de guerre {link:warlord-goretooth}Goretooth{/link} a dit à Thal'trak de passer à autre chose. Thal'trak ne peut quitter son poste, et il ne peut passer à autre chose.]=],
		},
		{
			title = "Importance",
			text = [=[Thal'trak rappelle que la guerre dans la montagne se paie du sang des simples soldats et de ceux qui les attendent.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie un chercheur apprendre ce qu'il est advenu de Sha'ni.
• Il réclame l'anneau de nez qu'elle portait, pris par l'{link:ogres}ogre{/link} {link:krom-grul}Krom'Grul{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le Rocher des Cognepeurs",
			hint = [=[Découvrez le sort de la femme de Thal'trak dans les Steppes ardentes.]=],
			text = [=[Sha'ni ne rentrerait pas. Elle et Thal'trak avaient prévu de vivre chez ses parents, dans {link:the-hinterlands}les Hinterlands{/link}, une fois leurs campagnes achevées. Tout ce qui revint à {link:kargath}Kargath{/link} fut son anneau de nez, repris à l'{link:ogres}ogre{/link} {link:krom-grul}Krom'Grul{/link} dans les grottes du {link:dreadmaul-rock}Rocher des Cognepeurs{/link}.]=],
		},
	},
	mentions = {
		{ text = "Le {link:dreadmaul-rock}Rocher des Cognepeurs{/link}" },
		{ text = "{link:krom-grul}Krom'Grul{/link}" },
	},
	bonds = {
		{ id = "sha-ni-proudtusk", name = "Sha'ni Proudtusk", note = "sa femme" },
		{ id = "warlord-goretooth", name = "Seigneur de guerre Goretooth", note = "son commandant" },
	},
})

Translate("frFR", "neeka-bloodscar", {
	title = "Neeka Bloodscar",
	subtitle = "Éclaireuse en chef de Kargath",
	found = "Kargath",
	hint = "Parlez à l'éclaireuse en chef de Kargath.",
	allegiance = "Horde · Kargath",
