		{
			title = "Résumé",
			text = [=[Neeka Bloodscar est l'éclaireuse en chef de {link:kargath}Kargath{/link}. Les {link:badlands}Terres ingrates{/link} sont proches des terres de l'{link:alliance}Alliance{/link} du {link:loch-modan}Loch Modan{/link}, et la route entre Kargath et {link:stonard}Stonard{/link} est longue et dangereuse. Ses coureurs n'arrivent pas toujours. Elle juge les nouveaux venus à leur capacité de survivre à la chaleur et aux bêtes des Terres ingrates.]=],
		},
		{
			title = "Importance",
			text = [=[Neeka maintient le lien entre {link:kargath}Kargath{/link} et le reste de la {link:horde}Horde{/link} à l'est. Ses rapports disent que l'{link:alliance}Alliance{/link} a ses propres ennuis, et que certains de ses ennemis pourraient bien être aussi ceux de la Horde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoie des rapports à {link:helgrum-the-swift}Helgrum le Rapide{/link}, à {link:stonard}Stonard{/link}.
• Elle met à prix les coyotes des rochers qui volent la nourriture de {link:kargath}Kargath{/link}.]=],
		},
	},
	mentions = {
		{ text = "Neeka Bloodscar" },
		{ text = "Les coyotes voleurs" },
		{ text = "Rapport à {link:helgrum-the-swift}Helgrum{/link}" },
	},
	bonds = {
		{ id = "helgrum-the-swift", name = "Helgrum le Rapide", note = "reçoit ses rapports" },
	},
})

Translate("frFR", "jarkal-mossmeld", {
	title = "Jarkal Mossmeld",
	subtitle = "Alchimiste de Kargath",
	found = "Kargath",
	hint = "Parlez à l'alchimiste troll de Kargath.",
	allegiance = "Horde · Kargath",
	aliases = { "Jarkal" },
	sections = {
		{
			title = "Résumé",
			text = [=[Jarkal Mossmeld est un alchimiste troll d'un certain renom qui travaille à {link:kargath}Kargath{/link}. Il achète les composants des {link:badlands}Terres ingrates{/link} et les champignons d'{link:uldaman}Uldaman{/link}, et il brasse des élixirs revigorants dont il est fier. Il a aussi le don des langues, et il se fait un devoir de savoir ce que cherchent les voyageurs avant qu'ils ne le lui disent.]=],
		},
		{
			title = "Importance",
			text = [=[Jarkal se dit un troll de parole, et il la tient, à sa manière. Quand les récupérateurs d'{link:orgrimmar}Orgrimmar{/link} envoyèrent un chercheur trouver un collier brisé dans {link:uldaman}Uldaman{/link}, Jarkal traduisit le journal qui contenait les indices. En échange, il étudia le collier, garda sa source d'énergie et apprit à en fabriquer d'autres. Les récupérateurs n'en surent jamais rien.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rassemble gésiers de charognard, crocs de coyote, éclats de roche et chapeaux de champignon magenta pour son travail.
• Il recueille le sang des dragons gardiens roussis dans des récipients de thaumaturgie.
• Il traduit le journal d'un paladin mort, trouvé dans {link:uldaman}Uldaman{/link}.
• Il fabrique des colliers de puissance, un pour son aide et plusieurs à vendre.]=],
		},
	},
	mentions = {
		{ text = "Composants des {link:badlands}Terres ingrates{/link}" },
		{ text = "Composants d'{link:uldaman}Uldaman{/link}" },
		{ text = "Composants des {link:badlands}Terres ingrates{/link} II" },
		{ text = "La traduction du journal" },
		{ text = "La traduction du journal" },
		{ text = "Trouver les gemmes et la source d'énergie" },
		{ text = "Livrer les gemmes" },
		{ text = "Récupération du collier, troisième prise" },
	},
	bonds = {
		{ id = "dran-droffers", name = "Dran Droffers", note = "le récupérateur qu'il a dupé" },
	},
})

Translate("frFR", "gorn", {
	title = "Gorn",
	subtitle = "Orc de Kargath",
	found = "Kargath",
	hint = [=[Parlez à l'orc de Kargath qui voudrait effacer une tache sur l'honneur de la Horde.]=],
	allegiance = "Horde · Kargath",
	sections = {
		{
			title = "Résumé",
			text = [=[Gorn est un {link:orcs}orc{/link} de {link:kargath}Kargath{/link} qui se souvient de la {link:second-war}Deuxième Guerre{/link} avec honte. Durant cette guerre, la {link:horde}Horde{/link} se tint alliée à {link:deathwing}Aile-de-mort{/link}, et deux des lieutenants du dragon, {link:blacklash}Blacklash{/link} et {link:hematus}Hematus{/link}, reposent toujours enchaînés sous le {link:lethlor-ravine}Ravin de Lethlor{/link}. Gorn entend faire taire les alliés dépravés d'autrefois de la Horde, pour restaurer son honneur.]=],
		},
		{
			title = "Importance",
			text = [=[Gorn exprime le désir de la nouvelle {link:horde}Horde{/link} de laisser derrière elle les crimes de l'ancienne. Il exprime aussi les dures leçons qu'elle a tirées des {link:ogres}ogres{/link}, qui ne font plus partie de la Horde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il engagea les ogres du chef {link:boss-tho-grun}Tho'grun{/link} pour prendre le Signe de la Terre, et ils le trahirent.
• Il envoie les combattants de {link:kargath}Kargath{/link} reprendre le Signe et briser le sceau de {link:lethlor-ravine}Lethlor{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Alliances brisées",
			hint = [=[Aidez l'orc de Kargath à mettre à mort les lieutenants d'Aile-de-mort.]=],
			text = [=[Le Signe de la Terre revint à {link:kargath}Kargath{/link}, et les drakes de {link:lethlor-ravine}Lethlor{/link} ne furent libérés que pour être tués. Gorn y vit une étape de plus. Le vol noir se tenait toujours aux côtés des orcs renégats {link:blackrock-mountain}Blackrock{/link}, et il fallait soumettre ou éliminer les uns comme les autres. Les drakes morts, Kargath pouvait tourner les yeux vers l'ouest, vers le {red:blackrock-spire}Pic Blackrock{/red}.]=],
		},
	},
	mentions = {
		{
			text = [=[Alliances brisées, la trahison de {link:boss-tho-grun}Tho'grun{/link}]=],
		},
		{ text = "Alliances brisées, les drakes abattus" },
		{ text = "Le Sceau de la Terre" },
	},
	bonds = {
		{ id = "boss-tho-grun", name = "Chef Tho'grun", note = "l'a trahi" },
		{ id = "blacklash", name = "Blacklash", note = "un allié d'autrefois qu'il voudrait faire taire" },
		{ id = "hematus", name = "Hematus", note = "un allié d'autrefois qu'il voudrait faire taire" },
	},
})

Translate("frFR", "thorkaf-dragoneye", {
